use codeint_model::language::SourceSet;

#[cfg(test)]
mod tests;

const TEST_FOLDERS: [&str; 2] = ["tests", "test"];

const GENERATED_MARKERS: [&str; 6] = [
    "@generated",
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "do not edit",
    "generated by",
];

pub(crate) fn classify(path: &str, header_comments: &str) -> SourceSet {
    let lower = header_comments.to_ascii_lowercase();
    if GENERATED_MARKERS
        .iter()
        .any(|marker| lower.contains(marker))
    {
        return SourceSet::Generated;
    }
    if is_test_path(path) {
        return SourceSet::Test;
    }
    SourceSet::Production
}

fn is_test_path(path: &str) -> bool {
    let (parent, file_name) = path.rsplit_once('/').unwrap_or(("", path));
    let in_test_dir = parent.split('/').any(|dir| TEST_FOLDERS.contains(&dir));
    let has_test_suffix = ["Test.php", ".test.php"]
        .into_iter()
        .any(|suffix| file_name.ends_with(suffix) && file_name.len() > suffix.len());
    in_test_dir || has_test_suffix
}
